"""One A entry: finish the own image and build coordinated Runtime/FC candidates."""
import argparse
import base64
import hashlib
import json
import os
from pathlib import Path
import platform
import shutil
import socket
import subprocess
import sys
import zlib

# The delivery generator inserts exact published source and reviewed helpers.
PAYLOAD = {'core-source.tar.gz': {'bytes': 2367740, 'sha256': '259a98868c7451e86cd212001a4f8bcc217d175a9ce020a018bf4a214c2ba27f', 'data': ''}, 'finish-rootfs.py': {'bytes': 9084, 'sha256': 'ab88deb49a6bc3326496745bfc24935829cf9541a720d865b6623abf83c26cab', 'data': ''}, 'fc-old-input-pins.json': {'bytes': 841, 'sha256': '1c35a6e538b712fb56f8762322a2c8a46f0525bb9797b88394e8a0a889b61655', 'data': ''}, 'fc-replacements.json': {'bytes': 79864, 'sha256': '7bc204d91454ab3b5ae9455d8239e235125eb3e47083e43196106dfd5581acab', 'data': ''}}
CORE_COMMIT = 'ccd03169cc217590d25c6daa04e576d175d67772'
ROOT = Path('/home/jwk/agent')
WORK = ROOT / 'builds/native-release-v3'
FINISH = ROOT / 'builds/rootfs-compact-finish-v2/return.json'
EXPORT_HELPER_SHA = '424ddd4cb3edc36f52b79081fedbfda67fed569578df0d7a323824611d94e048'
GIB = 1024**3


def need(ok, message):
    if not ok:
        raise RuntimeError(message)


def unpack(name):
    item = PAYLOAD[name]
    data = zlib.decompress(base64.b64decode(item['data'], validate=True))
    need(len(data) == item['bytes'] and hashlib.sha256(data).hexdigest() == item['sha256'], 'Embedded source differs: ' + name)
    return data


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--run', action='store_true')
    args = parser.parse_args()
    report = {'revision': 'A-coordinated-native-release-v3', 'status': 'PLAN_ONLY', 'coreCommit': CORE_COMMIT,
              'SDK_called': False, 'Guest_created': False, 'servicesChanged': False, 'phases': {},
              'workDirectory': str(WORK), 'memfilePrivateCowImplemented': False,
              'pmemSnapshotHardwareAccepted': False, 'newServicesDeployed': False,
              'scope': 'Coordinated release preparation, not final cross-node CoW acceptance'}
    if not args.run:
        print(json.dumps(report, indent=2)); return 0
    made = False
    try:
        need(platform.system() == 'Linux' and platform.machine() == 'aarch64' and socket.gethostname() == 'server1', 'Use ARM64 node A')
        need(os.getuid() == os.geteuid() == 1204 and os.getgid() == os.getegid() == 1205, 'Use ordinary jwk')
        caps = dict(line.split(':', 1) for line in Path('/proc/self/status').read_text().splitlines() if ':' in line)
        need(all(int(caps[k].strip(), 16) == 0 for k in ('CapInh', 'CapPrm', 'CapEff', 'CapAmb')), 'Zero capabilities required')
        need(ROOT.resolve(strict=True) == ROOT and WORK.parent.resolve(strict=True) == WORK.parent,
             'Unexpected build parent')
        need(not WORK.exists() and not WORK.is_symlink(), 'Prior candidate attempt preserved; do not rerun')
        need(shutil.disk_usage(ROOT).free >= 16 * GIB, '16 GiB initial build headroom required')
        helper = ROOT / 'A_export_real_rootfs_v1.py'
        need(helper.resolve(strict=True) == helper and helper.is_file() and helper.stat().st_size == 26588, 'Existing export helper differs')
        helper_raw = helper.read_bytes()
        need(hashlib.sha256(helper_raw).hexdigest() == EXPORT_HELPER_SHA, 'Existing export helper hash differs')
        m = {'__name__': 'verified_build_helpers'}
        exec(compile(helper_raw, str(helper), 'exec'), m)
        m['WORK'] = WORK
        os.umask(0o077); WORK.mkdir(mode=0o700); made = True
        (WORK / 'tmp').mkdir(mode=0o700)
        finish_script = WORK / 'finish-rootfs.py'
        finish_script.write_bytes(unpack('finish-rootfs.py'))
        if not FINISH.exists():
            print('PHASE=finish_already_resized_image_no_repeated_resize', flush=True)
            outcome = subprocess.run([sys.executable, '-I', '-B', str(finish_script), '--run'])
            report['rootfsFinishExit'] = outcome.returncode
        if FINISH.exists():
            report['rootfsFinish'] = json.loads(m['read'](FINISH))
        else:
            report['rootfsFinish'] = {'status': 'NO_FINISH_RECEIPT'}
        report['rootfsReady'] = report['rootfsFinish'].get('status') == 'REAL_ROOTFS_READY_FOR_UB_PUBLICATION_NOT_YET_PUBLISHED'
        # The binary build is independent of image validation; collect both in
        # one run even when the image needs a specific later correction.
        archive = unpack('core-source.tar.gz')
        m['ARCHIVE_SHA'] = hashlib.sha256(archive).hexdigest()
        source = m['unpack_source'](archive, WORK / 'core-source')
        need(hashlib.sha256(m['read'](source / 'Cargo.lock')).hexdigest() == m['LOCK_SHA'], 'Frozen core lock differs')
        rust = m['RUST']
        native = m['BASE'] / 'native'
        env = {'HOME': str(Path.home()), 'USER': 'jwk', 'LOGNAME': 'jwk', 'LANG': 'C.UTF-8',
               'PATH': str(rust) + ':' + str(native / 'bin') + ':/usr/local/bin:/usr/local/sbin:/usr/bin:/usr/sbin:/bin:/sbin', 'CARGO_HOME': str(m['CARGO_HOME']),
               'CARGO_TARGET_DIR': str(m['TARGET']), 'CARGO_NET_OFFLINE': 'true', 'CARGO_BUILD_JOBS': '2',
               'CARGO_INCREMENTAL': '0', 'RUSTC': str(rust / 'rustc'), 'RUSTDOC': str(rust / 'rustdoc'),
               'CARGO_PROFILE_RELEASE_LTO': 'false', 'CARGO_PROFILE_RELEASE_DEBUG': '0',
               'LIBCLANG_PATH': '/usr/lib64', 'CMAKE_BUILD_PARALLEL_LEVEL': '2', 'PROTOC': '/usr/local/bin/protoc',
               'LD_LIBRARY_PATH': str(native / 'lib') + ':' + str(native / 'fallback/lib'),
               'TMPDIR': str(WORK / 'tmp'), 'GIT_TERMINAL_PROMPT': '0', 'GIT_CONFIG_NOSYSTEM': '1',
               'GIT_CONFIG_GLOBAL': os.devnull, 'GIT_CEILING_DIRECTORIES': str(WORK)}
        pkg_dirs = [p for p in (native / 'lib/pkgconfig', ROOT / 'native/lib64/pkgconfig') if p.is_dir()]
        if pkg_dirs:
            env['PKG_CONFIG_PATH'] = ':'.join(map(str, pkg_dirs))
        prior_build = json.loads(m['read'](ROOT / 'builds/agentenv-native-fe63038/return.json'))
        need(prior_build.get('status') == 'THREE_CORE_BINARIES_BUILT_STAGED_NOT_DEPLOYED', 'Prior successful build receipt required')
        for key, patterns in (('ROCKSDB_LIB_DIR', ('librocksdb.*',)), ('SNAPPY_LIB_DIR', ('libsnappy.*',)),
                              ('LIBCLANG_PATH', ('libclang.so*', 'libclang-*.so*'))):
            value = prior_build.get('explicitNativeBuildDirectories', {}).get(key)
            if value:
                directory = Path(value)
                need(directory.is_absolute() and directory.resolve(strict=True) == directory and directory.is_dir()
                     and any(any(directory.glob(pattern)) for pattern in patterns), 'Prior native dependency changed: ' + key)
                env[key] = str(directory)
        cargo = str(rust / 'cargo')
        m['run']([cargo, 'build', '--release', '--offline', '--locked', '-p', 'agentenv', '--bin', 'server',
                  '-p', 'aenv', '--bin', 'aenv', '-p', 'uvm-ublk-daemon', '--bin', 'uvm-ublk-daemon'],
                 'build-coordinated-runtime', source, env, report)
        m['run']([cargo, 'build', '--release', '--offline', '--locked', '--manifest-path',
                  str(source / 'components/native-fd-verifier/Cargo.toml')], 'build-verifier', source, env, report)
        old = ROOT / 'builds/fc-native-pmem-v1'
        fc_source = ROOT / 'builds/fc-gnu-integrated-v1/source'
        pins = json.loads(unpack('fc-old-input-pins.json'))
        for name, pin in pins.items():
            need(hashlib.sha256(m['read'](fc_source / name, 4 * 1024**2)).hexdigest() == pin, 'Previous FC source differs: ' + name)
        files = list(fc_source.rglob('*'))
        need(len(files) <= 5000 and all(not f.is_symlink() for f in files), 'Unexpected FC source tree')
        destination = WORK / 'fc-source'
        shutil.copytree(fc_source, destination, ignore=shutil.ignore_patterns('.git', 'target', 'build'))
        replacements = json.loads(unpack('fc-replacements.json'))
        for name, encoded in replacements.items():
            need(name in pins or name == 'src/vmm/src/devices/virtio/pmem/native_snapshot.rs', 'Unexpected FC replacement path')
            (destination / name).write_bytes(base64.b64decode(encoded, validate=True))
        fc_env = dict(env, CARGO_HOME=str(old / 'cargo-home'), CARGO_TARGET_DIR=str(old / 'stage/fc-target'),
                      LIBRARY_PATH=str(old / 'stage/private-lib'), LD_LIBRARY_PATH=str(old / 'stage/private-lib'))
        m['run']([cargo, 'build', '--release', '--frozen', '--offline', '--manifest-path', str(destination / 'Cargo.toml'),
                  '--target', 'aarch64-unknown-linux-gnu', '-p', 'firecracker', '--bin', 'firecracker',
                  '--message-format=json-render-diagnostics'], 'build-snapshot-firecracker', destination, fc_env, report)
        # Run the exact shared protocol modules as a small native test crate.
        tests = WORK / 'protocol-tests'; tests.mkdir(mode=0o700)
        (tests / 'Cargo.toml').write_text('[package]\nname="native-pmem-release-tests"\nversion="0.1.0"\nedition="2021"\n'
            '[workspace]\n[lib]\npath="lib.rs"\n[dependencies]\nlibc="0.2.174"\nserde={version="1.0",features=["derive"]}\nserde_json="1.0"\n')
        module_root = source / 'components/firecracker-native-pmem'
        (tests / 'lib.rs').write_text(''.join('#[path = ' + json.dumps(str(module_root / (name + '.rs'))) + ']\npub mod ' + name + ';\n'
                                             for name in ('native_fd', 'native_snapshot')))
        frozen = m['read'](source / 'Cargo.lock'); (tests / 'Cargo.lock').write_bytes(frozen)
        m['run']([cargo, 'metadata', '--offline', '--format-version', '1', '--manifest-path', str(tests / 'Cargo.toml')],
                 'resolve-native-protocol-tests', tests, env, report, 120)
        import tomllib
        def registry_set(raw):
            return {(p['name'], p['version'], p.get('source'), p.get('checksum')) for p in tomllib.loads(raw.decode()).get('package', []) if p.get('source')}
        need(registry_set(m['read'](tests / 'Cargo.lock')) <= registry_set(frozen), 'Protocol test dependency drift')
        m['run']([cargo, 'test', '--release', '--offline', '--locked', '--manifest-path', str(tests / 'Cargo.toml'), '--lib'],
                 'run-native-protocol-tests', tests, env, report)
        artifacts = WORK / 'artifacts'; artifacts.mkdir(mode=0o700)
        paths = {n: m['TARGET'] / 'release' / n for n in ('server', 'aenv', 'uvm-ublk-daemon', 'aenv-native-fd-verify')}
        paths['firecracker'] = old / 'stage/fc-target/aarch64-unknown-linux-gnu/release/firecracker'
        report['artifacts'] = {}
        policy_candidates = set()
        for line in (WORK / 'build-snapshot-firecracker.log').read_text(errors='replace').splitlines():
            try: row = json.loads(line)
            except ValueError: continue
            if row.get('reason') == 'build-script-executed' and row.get('out_dir'):
                directory = Path(row['out_dir'])
                if directory.parent.name.startswith('firecracker-'): policy_candidates.add(directory / 'seccomp_filter.bpf')
        need(len(policy_candidates) == 1, 'One actual FC policy output required')
        policy = m['read'](policy_candidates.pop(), 65536)
        need(hashlib.sha256(policy).hexdigest() == 'afa4de05b17b89dec5c9a8f03b4852f836b45b28c76f6bdde812bd84ede2af00', 'Built-in policy differs')
        for name, path in paths.items():
            data = m['read'](path, 256 * 1024**2)
            need(data[:6] == b'\x7fELF\x02\x01' and int.from_bytes(data[18:20], 'little') == 183, 'Expected AArch64 ELF: ' + name)
            if name == 'firecracker': need(policy in data, 'Policy absent from FC binary')
            target = artifacts / name
            with target.open('xb') as stream: stream.write(data)
            target.chmod(0o700)
            report['artifacts'][name] = {'path': str(target), 'bytes': len(data), 'sha256': hashlib.sha256(data).hexdigest()}
        for name, pin in pins.items():
            need(hashlib.sha256(m['read'](fc_source / name, 4 * 1024**2)).hexdigest() == pin, 'Prior FC source changed')
        report['embeddedPolicySha256'] = hashlib.sha256(policy).hexdigest()
        report['status'] = 'COORDINATED_CANDIDATE_BINARIES_BUILT_NOT_DEPLOYED'
    except BaseException as error:
        report.update(status='STOPPED_RELEASE_PREPARATION_PRESERVE_ALL_OUTPUTS', errorType=type(error).__name__, reason=str(error)[:1500])
    finally:
        if made:
            with (WORK / 'return.json').open('x') as stream: json.dump(report, stream, indent=2)
        print('BEGIN_NATIVE_RELEASE_REPORT'); print(json.dumps(report, indent=2)); print('END_NATIVE_RELEASE_REPORT')
    return 0 if report['status'] == 'COORDINATED_CANDIDATE_BINARIES_BUILT_NOT_DEPLOYED' else 1


if __name__ == '__main__':
    raise SystemExit(main())
